package setup

// currentRoutingEditorScript drives the reviewer-only notification editor:
// rows are read-only forum routes, and the only editable state is the
// per-task-type reviewer target deltas.
func currentRoutingEditorScript() string {
	return `<script>
(function(){
  var form=document.querySelector('[data-current-routing-form]');if(!form)return;
  var panel=document.getElementById('production-wfa-detail-panel'),modal=document.querySelector('[data-wfa-add-modal]');
  var message=form.querySelector('[data-apply-message]'),pending=form.querySelector('[data-pending-status]'),apply=form.querySelector('[data-apply-submit]');
  var reviewerChanges={},activeRow=null;
  var addMessage=modal&&modal.querySelector('[data-wfa-add-message]');
  function clearAddMessage(){if(addMessage){addMessage.textContent='';addMessage.hidden=true}}
  function showAddMessage(label){if(addMessage){addMessage.textContent=label||'';addMessage.hidden=false}}
  function rows(){return Array.prototype.slice.call(form.querySelectorAll('[data-routing-row]'))}
  function typeID(row){return row?row.dataset.taskType:''}
  function targets(row){try{var raw=atob(row.dataset.existingTargets||'W10='),bytes=Uint8Array.from(raw,function(ch){return ch.charCodeAt(0)}),parsed=JSON.parse(new TextDecoder().decode(bytes));return Array.isArray(parsed)?parsed:[]}catch(_){return []}}
  function delta(id){return reviewerChanges[id]||(reviewerChanges[id]={add_user_ids:[],remove_user_ids:[],add_role_ids:[],remove_role_ids:[]})}
  function selectedOption(select,value){return select?Array.prototype.find.call(select.options,function(option){return option.value===value}):null}
  function updateRoleEligibility(){if(!modal)return;var eligibleIDs=new Set(activeRow?((activeRow.dataset.roleEligibleIds||'').split(',').filter(Boolean)):[]),available=0;modal.querySelectorAll('[data-wfa-role-listbox] [role="option"]').forEach(function(option){var enabled=eligibleIDs.has(option.dataset.wfaOptionValue||''),label=option.dataset.roleName||option.textContent,reason='';if(!enabled)reason=option.dataset.roleDisabledLabel||modal.dataset.rolePermissionLabel||'';option.setAttribute('aria-disabled',String(!enabled));option.classList.toggle('recipient-option-disabled',!enabled);option.textContent=reason?label+' — '+reason:label;if(enabled)available++});var select=modal.querySelector('[data-wfa-role-id]');if(select)Array.prototype.forEach.call(select.options,function(option){if(!option.value)return;var item=modal.querySelector('[data-wfa-role-listbox] [data-wfa-option-value="'+CSS.escape(option.value)+'"]');option.disabled=!item||item.getAttribute('aria-disabled')==='true'});modal.dataset.hasRoleOptions=String(available>0);var confirm=modal.querySelector('[data-wfa-add-confirm]');if(confirm&&modal.dataset.recipientMode==='role')confirm.disabled=available===0}
  function renderTargets(row){var list=panel.querySelector('[data-wfa-target-list]');if(!list)return;list.textContent='';var id=typeID(row),changes=delta(id),items=targets(row).filter(function(item){return changes[item.kind==='role'?'remove_role_ids':'remove_user_ids'].indexOf(item.id)<0});['user','role'].forEach(function(kind){changes[kind==='role'?'add_role_ids':'add_user_ids'].forEach(function(targetID){var select=modal&&modal.querySelector(kind==='role'?'[data-wfa-role-id]':'[data-wfa-user-id]'),option=select&&selectedOption(select,targetID);items.push({kind:kind,id:targetID,label:option?option.textContent:(kind==='role'?'@'+targetID:targetID)})})});items.forEach(function(item){var li=document.createElement('li'),name=document.createElement('span'),button=document.createElement('button');li.dataset.kind=item.kind;li.dataset.id=item.id;name.textContent=item.label;button.type='button';button.className='btn-ghost';button.dataset.wfaRemoveTarget='';button.textContent=form.dataset.removeLabel;li.appendChild(name);li.appendChild(button);list.appendChild(li)})}
  function selectRow(row){if(!row||!typeID(row))return;activeRow=row;rows().forEach(function(item){var selected=item===row;item.classList.toggle('selected',selected);item.setAttribute('aria-selected',String(selected));item.setAttribute('aria-expanded',String(selected));var button=item.querySelector('[data-select-task]');if(button){button.setAttribute('aria-pressed',String(selected));button.setAttribute('aria-expanded',String(selected))}});panel.hidden=false;panel.querySelector('[data-wfa-title]').textContent=row.dataset.taskTypeName||'';updateRoleEligibility();var source=form.parentElement.querySelector('[data-wfa-pending-source] [data-task-type-id="'+CSS.escape(typeID(row))+'"]'),sourceAuto=source&&source.querySelector('[data-wfa-automatic-value]'),auto=panel.querySelector('[data-wfa-automatic-value]');if(auto)auto.textContent=sourceAuto?(sourceAuto.dataset.wfaSummary||sourceAuto.textContent):form.dataset.emptyWfa;renderTargets(row);sync()}
  function targetChangeCount(){return Object.keys(reviewerChanges).reduce(function(total,id){var c=reviewerChanges[id];return total+c.add_user_ids.length+c.remove_user_ids.length+c.add_role_ids.length+c.remove_role_ids.length},0)}
  function sync(){var count=targetChangeCount();if(pending)pending.textContent=count===0?form.dataset.noPending:count+' '+(count===1?form.dataset.pendingOne:form.dataset.pendingMany)+' · '+form.dataset.pendingInstruction;if(apply)apply.disabled=count===0}
  rows().forEach(function(row){
    if(row.dataset.eventsBound==='true')return;row.dataset.eventsBound='true';
    row.addEventListener('click',function(event){var target=event.target;if(target&&target.closest&&target.closest('button,a,label,input,select,textarea,details,summary,[role="button"],[role="combobox"],[role="option"]'))return;selectRow(row)});
    row.addEventListener('keydown',function(event){if(event.target!==row||!['Enter',' '].includes(event.key))return;event.preventDefault();selectRow(row)});
    row.querySelector('[data-select-task]')&&row.querySelector('[data-select-task]').addEventListener('click',function(){selectRow(row)});
  });
  panel.addEventListener('click',function(event){var button=event.target.closest('[data-wfa-remove-target]');if(!button||!activeRow)return;var li=button.closest('li'),id=typeID(activeRow),kind=li.dataset.kind,targetID=li.dataset.id,c=delta(id),base=targets(activeRow).some(function(item){return item.kind===kind&&item.id===targetID}),key=kind==='role'?'remove_role_ids':'remove_user_ids',addKey=kind==='role'?'add_role_ids':'add_user_ids';if(base){if(c[key].indexOf(targetID)<0)c[key].push(targetID)}else c[addKey]=c[addKey].filter(function(value){return value!==targetID});renderTargets(activeRow);sync()});
  panel.querySelector('[data-wfa-add-target]')&&panel.querySelector('[data-wfa-add-target]').addEventListener('click',function(){if(activeRow&&modal&&modal.showModal){clearAddMessage();modal.dataset.recipientMode='user';modal.querySelector('#wfa-user-tab')&&modal.querySelector('#wfa-user-tab').click();modal.showModal();var combo=modal.querySelector('[data-wfa-user-combobox]');if(combo)combo.focus()}});
  modal&&modal.querySelectorAll('[role="tab"]').forEach(function(tab,index,tabs){tab.addEventListener('click',function(){clearAddMessage();var mode=tab.dataset.recipientMode;modal.dataset.recipientMode=mode;modal.querySelectorAll('[role="tab"]').forEach(function(item){var selected=item===tab;item.setAttribute('aria-selected',String(selected));item.tabIndex=selected?0:-1});modal.querySelectorAll('[data-recipient-panel]').forEach(function(item){item.hidden=item.dataset.recipientPanel!==mode});var confirm=modal.querySelector('[data-wfa-add-confirm]');if(confirm)confirm.disabled=mode==='role'&&modal.dataset.hasRoleOptions!=='true'});tab.addEventListener('keydown',function(event){if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();var next=event.key==='Home'?0:event.key==='End'?tabs.length-1:event.key==='ArrowRight'?(index+1)%tabs.length:(index+tabs.length-1)%tabs.length;tabs[next].click();tabs[next].focus()})});
  modal&&modal.querySelectorAll('[data-recipient-select]').forEach(function(select){select.addEventListener('change',clearAddMessage)});
  modal&&modal.querySelector('[data-wfa-add-cancel]')&&modal.querySelector('[data-wfa-add-cancel]').addEventListener('click',function(){clearAddMessage();modal.close()});
  modal&&modal.querySelector('[data-wfa-add-confirm]')&&modal.querySelector('[data-wfa-add-confirm]').addEventListener('click',function(){if(!activeRow){showAddMessage(modal.dataset.routeRequiredLabel);return}var kind=modal.dataset.recipientMode,select=modal.querySelector(kind==='role'?'[data-wfa-role-id]':'[data-wfa-user-id]'),id=select&&select.value;if(!id){showAddMessage(modal.dataset.targetRequiredLabel);return}clearAddMessage();var c=delta(typeID(activeRow)),base=targets(activeRow).some(function(item){return item.kind===kind&&item.id===id}),key=kind==='role'?'add_role_ids':'add_user_ids',removeKey=kind==='role'?'remove_role_ids':'remove_user_ids';if(base)c[removeKey]=c[removeKey].filter(function(value){return value!==id});else if(c[key].indexOf(id)<0)c[key].push(id);select.value='';modal.close();renderTargets(activeRow);sync()});
  var safeApplyErrors={production_not_writable:form.dataset.errorProductionNotWritable,stale_edit:form.dataset.staleMessage,reviewer_target_not_eligible:form.dataset.errorReviewerTarget,reviewer_eligibility_unavailable:form.dataset.errorReviewerUnavailable,reviewer_delta_for_removed_route:form.dataset.errorRouteRemoved};
  async function showApplyFailure(response){var code='';try{var body=await response.json();if(body&&typeof body.error==='string')code=body.error}catch(_){}message.textContent=safeApplyErrors[code]||form.dataset.errorMessage}
  form.addEventListener('submit',async function(event){event.preventDefault();message.textContent='';var changes=Object.keys(reviewerChanges).filter(function(id){var c=reviewerChanges[id];return c.add_user_ids.length||c.remove_user_ids.length||c.add_role_ids.length||c.remove_role_ids.length}).map(function(id){var c=reviewerChanges[id];return {task_type_id:id,add_user_ids:c.add_user_ids,remove_user_ids:c.remove_user_ids,add_role_ids:c.add_role_ids,remove_role_ids:c.remove_role_ids}}),payload={project_id:form.dataset.projectId,expected_revision:form.querySelector('[name="expected_revision"]').value,reviewer_changes:changes};apply.disabled=true;try{var response=await fetch(form.dataset.applyEndpoint,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify(payload),credentials:'same-origin'});if(response.ok){window.location.assign(form.dataset.successUrl);return}await showApplyFailure(response)}catch(_){message.textContent=form.dataset.errorMessage}finally{sync()}});
  sync();
})();
</script>`
}
